"""
    Binary Search
    Complexity: O(logN)

    Requires a sorted array.
    Small modifications needed to work
    with descending order as well.
    """
def binary_search(array: Any, element: Any) -> object {
    lower = 0;
    upper = len(array) - 1;
    while (lower <= upper) {
        mid = (lower + upper) // 2;
        if (array[mid] < element) {
            lower = mid + 1;
        } elif (array[mid] > element) {
            upper = mid - 1;
        } else {
            return mid;
        }
    }
    return -1;
}

"""Receive a dict of keys -> names and values -> a sequence of
      of programming languages, return the common languages"""
def common_languages(programmers: Any) -> object {
    languages = [`set(language) for language in programmers.values()];
    return `set.intersection(*languages);
}
